def get_Position(a, n, m):
    """Write a python function to find the position of the last removed element from the given array."""
    # Repeatedly remove every m-th element circularly until one remains.
    # The survivor (last removed when clearing the array) satisfies
    # J(1)=0, J(i)=(J(i-1)+m)%i, returned as 0-based original position.
    result = 0
    for i in range(2, n + 1):
        result = (result + m) % i
    return result
